import{_ as o,o as a,c as r,ag as u}from"./chunks/framework.D5hoimZQ.js";const g=JSON.parse('{"title":"09 刑侦司法与行业实录知识——从天涯亲历帖里提炼的\\"内行知识\\"","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/tianya/handbook/09_刑侦司法与行业实录知识.md","filePath":"topics/tianya/handbook/09_刑侦司法与行业实录知识.md"}'),q={name:"topics/tianya/handbook/09_刑侦司法与行业实录知识.md"};function e(n,t,s,h,i,l){return a(),r("div",null,[...t[0]||(t[0]=[u('<h1 id="_09-刑侦司法与行业实录知识——从天涯亲历帖里提炼的-内行知识" tabindex="-1">09 刑侦司法与行业实录知识——从天涯亲历帖里提炼的&quot;内行知识&quot; <a class="header-anchor" href="#_09-刑侦司法与行业实录知识——从天涯亲历帖里提炼的-内行知识" aria-label="Permalink to &quot;09 刑侦司法与行业实录知识——从天涯亲历帖里提炼的&quot;内行知识&quot;&quot;">​</a></h1><blockquote><p>本文的知识全部提炼自天涯原帖（帖号标注：126/155/181/144/110/141/188/128/163与172/168）。每条知识分两档：<strong>【实录】</strong>=帖内以亲历口吻陈述、且与公开制度或常识可互证的流程知识；<strong>【演绎】</strong>=文学设定或民间传说，只能当故事听，不可当真。判断标准写在文末。</p></blockquote><h2 id="一、刑警办案-从现场勘查到悬案" tabindex="-1">一、刑警办案：从现场勘查到悬案 <a class="header-anchor" href="#一、刑警办案-从现场勘查到悬案" aria-label="Permalink to &quot;一、刑警办案：从现场勘查到悬案&quot;">​</a></h2><h3 id="_1-现场勘查如何推导案情-126-1985年研究所凶案-全帖推演最完整的一例" tabindex="-1">1. 现场勘查如何推导案情（126，1985年研究所凶案，全帖推演最完整的一例） <a class="header-anchor" href="#_1-现场勘查如何推导案情-126-1985年研究所凶案-全帖推演最完整的一例" aria-label="Permalink to &quot;1. 现场勘查如何推导案情（126，1985年研究所凶案，全帖推演最完整的一例）&quot;">​</a></h3><p>**【实录】现场定性五步法。**第一步划活动区域：三室一厅的房子，凶手只翻动了客厅和洗手间，三间卧室根本没去——说明来意明确、目标单一。第二步排除谋财：卧室桌上明放着300元现金（当时是巨款），分文未动——定性为纯粹杀人。第三步还原进门手法：家属辨认出早上没有的两盒点心和一筐苹果，推出凶手借口送礼敲门、放下点心、让男孩低头倒苹果时动手。第四步从尸体反推凶手：法医未出报告时，老刑警凭伤形判断钝器击打；死者身高172不魁梧，而第一击就失去知觉、全楼无人听到呼救——推出凶手力气大、下手狠。第五步解释现场疑点：尸体最后的姿势是脑袋顶着门，凶手自己怎么出去？于是产生替代假说——男孩当时没死，凶手走后他试图爬到门口呼救，体力不支——这一步是刑侦思维的关键：<strong>现场每一个反常姿态都必须有解释，两种解释都保留，用后续证据裁决。</strong></p><p>**【实录】反侦查痕迹本身是线索。**门和把手上的指纹脚印被细心擦净——查不到人，但&quot;会擦拭现场&quot;这个事实本身就刻画了凶手的心理素质与预谋程度。</p><h3 id="_2-时间线如何锚定-126" tabindex="-1">2. 时间线如何锚定（126） <a class="header-anchor" href="#_2-时间线如何锚定-126" aria-label="Permalink to &quot;2. 时间线如何锚定（126）&quot;">​</a></h3><p>**【实录】用&quot;报时&quot;做时间戳。**对面楼老太太10点整在阳台看见一个蓝棉袄雷锋帽的男人，左手两盒点心、右手一个大布袋——她记得这么准，是因为看见那人进楼时，家里开着的收音机正好准点报时。这是全帖最漂亮的一笔：**证人记不住时间，但环境里有天然的报时器。**由此确定作案时间窗，再顺两条线排查：一路去公交公司（老太太肯定他是走着来的，查公交是验证而非假设），一路去点心的生产和销售点——两条线都落空，但&quot;落空&quot;本身也有信息：说明凶手不坐公交、点心未必自己买。</p><h3 id="_3-排查嫌疑人的标准动作-126" tabindex="-1">3. 排查嫌疑人的标准动作（126） <a class="header-anchor" href="#_3-排查嫌疑人的标准动作-126" aria-label="Permalink to &quot;3. 排查嫌疑人的标准动作（126）&quot;">​</a></h3><p>**【实录】动机—条件—时间三查。**先造嫌疑名单：与被害人有隙者（找副所长吵过架、动过手的后勤清洁工老王）、外形吻合者（身高172—176、偏瘦）、有条件骗开门者。再查时间证人：老王案发时在办公室睡觉，无人证明，仍有重大嫌疑；绘图员自称拉肚子，但医务室有开药记录、请过病假、全办公室都知道——消失的半小时不够作案，<strong>排除</strong>。最后换方向：查被害人的学校（无仇家）、查姐姐姐夫（无作案时间）。注意这套流程里没有一次靠&quot;直觉破案&quot;，全是排除法。</p><h3 id="_4-悬案为什么悬-126" tabindex="-1">4. 悬案为什么悬（126） <a class="header-anchor" href="#_4-悬案为什么悬-126" aria-label="Permalink to &quot;4. 悬案为什么悬（126）&quot;">​</a></h3><p>**【实录】证据链的三个断裂点。**①物证断：现场无指纹脚印、无凶器、无血衣，唯一的物证是凶手带来又&quot;留下&quot;的点心苹果——那是凶手的道具，不是失误。②证人断：唯一目击是远景一瞥，只够刻画衣着，不够刻画脸。③时间断：案子拖过黄金期，十年后的举报信（称幕后是所长、凶手是雇佣杀手、经办人是小舅子）因关键知情人&quot;是个老实人，不像能认识杀手的&quot;而无法证实，老刑警的结论只能停在假说层面——&quot;那个无辜的男孩很可能死于研究所内部派系斗争，只是一点线索和证据都没有&quot;。<strong>悬案的本质：不是没有答案，是没有可呈堂的证据。</strong></p><p><strong>【实录】另一种悬法：制度失灵。<strong>同帖1970年代初的党校教师失踪案——正值&quot;砸烂公检法&quot;，家属报警也没用；单位造反派头头一句&quot;人已经走了&quot;即脱责；文革结束后复职领导也只认&quot;一不是迫害致死、二不是在学校出事&quot;。悬案未必难在侦破技术，也可能难在</strong>当时根本无人侦破</strong>。</p><h3 id="_5-小物证破案法-155" tabindex="-1">5. 小物证破案法（155） <a class="header-anchor" href="#_5-小物证破案法-155" aria-label="Permalink to &quot;5. 小物证破案法（155）&quot;">​</a></h3><p>**【实录】反常即线索。**水上公园浮尸案：民警到嫌疑人家里，看见三件小事——夏天的早晨、没到做饭时间，炉子却生得很旺；炉子后面的墙上有一个快烘干的湿鞋印；床底翻出一双潮湿的男式新皮鞋。链条：夏天烤东西反常→鞋印说明烤过湿物→新皮鞋贵、死者衣服都烧了唯独皮鞋留着→女主人舍不得扔、想烤干给姘头穿。三条物证互锁，无需口供即破。<strong>方法论：不找&quot;大证据&quot;，找&quot;不该出现的东西&quot;。</strong></p><p>**【实录】观察-验证法。**劫持人质案：不能强攻，就架望远镜持续观察，看见劫犯拿&quot;枪&quot;点烟——枪点不了烟，那是一把打火机；所谓炸药包后经查是三十多个二踢脚捆的。威胁评估降级后才敢突入。同帖骗子案：便衣递上一份英语四级阅读理解冒充产品资料，&quot;特派员&quot;煞有介事夸翻译不错；再听他把日内瓦说成&quot;去过瑞典最迷人的城市&quot;——常识错误一穿帮，身份即假。</p><p>**【实录】机关大院的生人作案术（反诈知识）。**小偷闯进办公室，不等别人盘问先发制人训斥&quot;下午市里来人检查，屋子怎么这么乱&quot;，支使女孩扫地、倒茶、去会议室备茶杯，见路过者递纸&quot;帮复印三份&quot;，最后跟醉酒的主任谈&quot;洗空调罩子收100块&quot;讨价还价脱身。<strong>核心手法：给自己一个&quot;有权的生人&quot;身份，用指令性行为替代解释性行为。</strong></p><h3 id="_6-抓捕与执法的程序细节-155" tabindex="-1">6. 抓捕与执法的程序细节（155） <a class="header-anchor" href="#_6-抓捕与执法的程序细节-155" aria-label="Permalink to &quot;6. 抓捕与执法的程序细节（155）&quot;">​</a></h3><p>**【实录】**大案抓捕的标准画面（幻影擒魔案）：从模糊线索（上月被辞退、夜里不值班常溜出库房）→查暂住地→联系属地警方秘密布控→便衣开假装修车接近→嫌疑人低头拧螺栓时两人扑按、二十余名警察多方位合围。搜查的程序：先派小民警去拿搜查证，带队者引用《刑事诉讼法》&quot;执行逮捕、拘留的时候，遇有紧急情况，不另用搜查证也可以进行搜查&quot;——<strong>紧急搜查权的适用场景</strong>这是帖里最硬的法条知识。破案后随即按物证（多条女式衣物、首饰、断裂珍珠项链）追查更多受害人——外地卖淫女子被杀后无人报案、无声消失，是那类连环案长期不破的社会性原因。</p><p>**【帖内说法】**155作者在回复中称&quot;天津严重刑事案件破案率平均在90%以上&quot;——一家之言，无出处，仅供对照&quot;悬案帖&quot;的观感：能写出来的破案多，破不了的案子根本不会上帖。</p><h3 id="_7-对照-演义帖里的-警察-破绽-128" tabindex="-1">7. 对照：演义帖里的&quot;警察&quot;破绽（128） <a class="header-anchor" href="#_7-对照-演义帖里的-警察-破绽-128" aria-label="Permalink to &quot;7. 对照：演义帖里的&quot;警察&quot;破绽（128）&quot;">​</a></h3><p>**【演绎】**128《灵异警事》的警察知识只剩流程名词：专案组开会、刑事鉴证科、DNA检验报告——但DNA当天出结果、刑警一言不合被抽调去&quot;猎灵局天津分局&quot;管鬼案、律师给同居情侣起草&quot;互禁碰对方乌木匣&quot;的财产协议，全是小说权限。判别式：<strong>实录帖的警察受制于程序（要搜查证、怕立不了案、请示领导），演义帖的警察无所不能。</strong></p><h2 id="二、检察官与刑事司法-181-全组司法知识最密集的一帖" tabindex="-1">二、检察官与刑事司法（181，全组司法知识最密集的一帖） <a class="header-anchor" href="#二、检察官与刑事司法-181-全组司法知识最密集的一帖" aria-label="Permalink to &quot;二、检察官与刑事司法（181，全组司法知识最密集的一帖）&quot;">​</a></h2><h3 id="_1-审查起诉的实际标准" tabindex="-1">1. 审查起诉的实际标准 <a class="header-anchor" href="#_1-审查起诉的实际标准" aria-label="Permalink to &quot;1. 审查起诉的实际标准&quot;">​</a></h3><p><strong>【实录】&quot;到不了检察院&quot;意味着什么。<strong>教师猥亵案：女童口供只有&quot;老师喜欢摸头摸后背、偶尔抱抱&quot;，警察的原话是&quot;凭你侄女的这几句话很难追究他的刑事责任&quot;&quot;这种口供就像娱乐八卦里说女星出轨但没有实锤&quot;。猥亵类案件要追究刑责，必须有确凿证据；证据不足连立案都难，更进不了审查起诉。检察官的破局动作：引导受害人回忆</strong>有具体时间、地点、动作细节</strong>的事件——把模糊感受转化为可查证的陈述，再找到另一名受害女生相互印证，案子才立起来。<strong>知识：被害人陈述的证据化，靠细节而非情绪。</strong></p><h3 id="_2-口供不是必需品-零口供如何定案" tabindex="-1">2. 口供不是必需品：零口供如何定案 <a class="header-anchor" href="#_2-口供不是必需品-零口供如何定案" aria-label="Permalink to &quot;2. 口供不是必需品：零口供如何定案&quot;">​</a></h3><p>**【实录】证据链清单。**七年积案（蒙面入室强奸多人）最终告破，靠的不是口供而是：看守所内犯人检举揭发（号房吹牛&quot;阅女无数&quot;）→管教警觉（此人竟无任何前科，连治安处罚都没有——反常）→抽血比对DNA，与三起积案物证吻合→提取笔录+检验报告呈堂。被告人全程死不认罪，照样起诉判刑。</p><p>**【实录】被告人&quot;比你还懂法&quot;时的攻防。**小偷当庭翻供：&quot;公诉人你发现所有的精斑都是从裤子上提取的，不觉得不够严谨吗？我承认案子是我做的，但我没有强奸她们。&quot;前两起确实只在裤子上提取到精斑（当时提取到了就没有再做阴道内检测）——<strong>物证提取的顺序漏洞被被告人反向利用</strong>。法官的处置：不硬顶，就第三起（阴道内也提取到吻合精斑）咨询医生&quot;这样用手能否把精液带进去&quot;，答案是&quot;存在一定概率的可能&quot;。结果：两起改定强制猥亵，一起结合鉴定报告与被害人陈述定强奸；本该十年以上的刑期，两罪并罚只判六年。<strong>知识：罪名随证据强度收缩，是司法的常态而非耻辱；辩护人式的狡辩能改变量刑，很难推翻DNA。</strong></p><h3 id="_3-司法精神病鉴定与刑事责任能力" tabindex="-1">3. 司法精神病鉴定与刑事责任能力 <a class="header-anchor" href="#_3-司法精神病鉴定与刑事责任能力" aria-label="Permalink to &quot;3. 司法精神病鉴定与刑事责任能力&quot;">​</a></h3><p>**【实录】启动与判定流程。<strong>变性人大飞盗窃案：检察官听完其异常言行（初次提审即倾诉、扬言喜欢被男性追求、自曝偷窃动机是&quot;进拘留所有犯人搂着睡觉&quot;），<strong>向领导汇报并正式提出</strong>应对大飞做精神疾病鉴定，以确保其刑事责任能力。鉴定结论：躁狂症（情绪高涨、性欲亢进、举止轻浮、喜欢挑逗接近异性）。但关键判定在下一句：</strong>&quot;作案时对自己的盗窃行为具有完全认知和判断能力，所以对本案仍然具有完全刑事责任能力&quot;，法院依法判决。**知识：患精神病≠免责，看的是作案时的辨认与控制能力。</p><h3 id="_4-伤情鉴定决定案件性质" tabindex="-1">4. 伤情鉴定决定案件性质 <a class="header-anchor" href="#_4-伤情鉴定决定案件性质" aria-label="Permalink to &quot;4. 伤情鉴定决定案件性质&quot;">​</a></h3><p>**【实录】**张老汉被儿子推倒受伤，伤情鉴定构成轻伤→儿子随即被刑事拘留，故意伤害进入刑事程序；父亲以&quot;让出房子&quot;为和解条件，儿子宁坐牢不答应——<strong>轻伤案的刑事追诉权在受害人意愿与和解博弈中运作</strong>，这是基层司法最常见的现实。</p><h3 id="_5-性侵未成年人的行业观察-181" tabindex="-1">5. 性侵未成年人的行业观察（181） <a class="header-anchor" href="#_5-性侵未成年人的行业观察-181" aria-label="Permalink to &quot;5. 性侵未成年人的行业观察（181）&quot;">​</a></h3><p><strong>【实录】</strong>&quot;我经历的女孩被侵犯的案子无一例外都发生在小学及以下这段期间，而且没有一个在被害之后主动选择报警或向家长诉说。&quot;全班第一排学生目猥亵全程无一人出声——检察官的解释：八九岁孩子面对的是权威，而且&quot;根本不知道老师把手伸进裤子里是干嘛的&quot;。制度后果：案发后该小学男老师全部调离。赔偿环节的现实：加害方亲属知道赔偿也换不来减刑，索性分文不给；办案头儿的反思是母亲为索赔二次揭开孩子伤疤&quot;做法欠妥&quot;。<strong>知识：儿童性侵案的第一障碍不是侦查，是无人报案。</strong></p><h3 id="_6-庭审与刑期的冷知识-181" tabindex="-1">6. 庭审与刑期的冷知识（181） <a class="header-anchor" href="#_6-庭审与刑期的冷知识-181" aria-label="Permalink to &quot;6. 庭审与刑期的冷知识（181）&quot;">​</a></h3><p>**【实录】**强奸案不公开开庭——被告妻子只能带着儿子在法庭外等&quot;让儿子看一眼爸爸、听一声爸爸&quot;；&quot;强奸多人&quot;是十年以上量刑档；上诉后中院维持原判。</p><h2 id="三、殡葬行业-144-110-两帖互补-144给机构流程-110给行规民俗" tabindex="-1">三、殡葬行业（144+110，两帖互补：144给机构流程，110给行规民俗） <a class="header-anchor" href="#三、殡葬行业-144-110-两帖互补-144给机构流程-110给行规民俗" aria-label="Permalink to &quot;三、殡葬行业（144+110，两帖互补：144给机构流程，110给行规民俗）&quot;">​</a></h2><h3 id="_1-基层殡仪馆的组织与业务流程" tabindex="-1">1. 基层殡仪馆的组织与业务流程 <a class="header-anchor" href="#_1-基层殡仪馆的组织与业务流程" aria-label="Permalink to &quot;1. 基层殡仪馆的组织与业务流程&quot;">​</a></h3><p>**【实录】机构与分工（144）。**两万人的小镇，殡仪馆编制5人：所长、副所长、大嘴（开车+布灵堂）、外聘修坟的王师傅、挂名不干活的张阿八，业务由老朱管。镇馆没有火化设备，<strong>要拉着尸体跑80多公里去J市火化</strong>；运尸车是11座金杯面包改装：前后用铁皮隔开，前头放尸，家属多时后厢加两条长凳，但后厢规定绝不坐人。行话把送尸叫&quot;跑业务&quot;。完整服务链（144局长丈人案）：<strong>送火化→布置灵堂→追悼仪式→上山入土</strong>，每一个环节所长亲自督办；事毕有白喜酒，领导一句&quot;手机落在单位了&quot;就得夜里回馆去拿——基层单位的权力生态与殡葬同行。</p><p>**【实录】设施与日常（144）。**存尸房是灵堂右侧小道旁一幢仓库模样的房子，放冰柜；无名尸火化后骨灰无人认领（逾期被弃）是行业真问题；殡仪馆周边无路灯，夜里全黑；车里挂桃树枝，夜间进馆的心理技术——开大灯（100瓦白炽灯&quot;如沐春光&quot;）、大声咳嗽、哼歌给自己壮胆。</p><h3 id="_2-收殓与行规-110" tabindex="-1">2. 收殓与行规（110） <a class="header-anchor" href="#_2-收殓与行规-110" aria-label="Permalink to &quot;2. 收殓与行规（110）&quot;">​</a></h3><p><strong>【实录】棺与椁。</strong>&quot;棺装死人，椁套在棺外放殉葬品&quot;，两层，椁与棺的夹层里放冰块降温防腐，好棺材开棺时尸身&quot;没有起黑点、没有腐臭&quot;。**【实录】同行暗号：<strong>墨斗线打&quot;七星旋扣&quot;是行内人才会的结法，后到者一看便知尸体已被同行处理过，要按规矩来。</strong>【实录】缝头工艺：<strong>火车轧掉脑袋的，用布缝个假脑袋，让家属能见全尸下葬；刀斩犯缝头是老传统，车祸缝头是现代版，一针一针缝回去。</strong>【实录】行业铁忌：<strong>脱死者的衣物属于猥亵尸体，是行内大忌；遇诡异现象，先磕头赔罪——&quot;是他们的地盘&quot;。</strong>【实录】从业者生态：<strong>收入过得去（&quot;死者为大&quot;，人家不会计较），但孩子从小被全村忌讳、上学都受影响——这是110里最真实的社会学细节。</strong>【实录】备喜棺（110/144两帖互证）：**老人过花甲就提前打棺材，当自家房子一样备着、上漆，老人心里踏实，不算晦气。</p><h3 id="_3-湘西赶尸-传说层的标准版本-110" tabindex="-1">3. 湘西赶尸：传说层的标准版本（110） <a class="header-anchor" href="#_3-湘西赶尸-传说层的标准版本-110" aria-label="Permalink to &quot;3. 湘西赶尸：传说层的标准版本（110）&quot;">​</a></h3><p>**【演绎（民俗传说）】**辰州符、辰州砂；赶尸前先验尸，封七处关窍留住七魄——脑门心、背膛心、胸膛心窝、左右手板心、脚掌心；耳、鼻、口是三魂出入之所，要用辰州砂封死；若无辰州砂，用定针法替代（银针封窍）；启程时喝一声&quot;起！&quot;。此套知识在民俗学上有流传文本，但&quot;尸体自行行走&quot;从未被证实；110把它讲得头头是道，恰是&quot;传说考&quot;而非&quot;实录&quot;。</p><h3 id="_4-民俗疗法的仪式细节-144黄师傅" tabindex="-1">4. 民俗疗法的仪式细节（144黄师傅） <a class="header-anchor" href="#_4-民俗疗法的仪式细节-144黄师傅" aria-label="Permalink to &quot;4. 民俗疗法的仪式细节（144黄师傅）&quot;">​</a></h3><p><strong>【演绎（民俗）】<strong>民间端公的完整生态：驱邪看病</strong>从不收钱，就爱喝口酒</strong>（登门带几瓶好酒即是礼）；望气断症——&quot;一看你面孤，就晓得你中了邪&quot;；朱砂符水的操作：草纸对折撕两片，毛笔蘸朱砂画符，烧成灰混入清水灌服，吐后即愈（帖内&quot;案例&quot;以现代医学看当属癔症发作与暗示疗法）；被&quot;鬼摸&quot;后手上起青黑掌印的解法：<strong>半斤糯米加高度酒蒸熟，敷在掌印上，一天两次，三四天拔尽阴毒</strong>（糯米拔毒确是民间通用方，也用于拔弹片异物，此处属附会）；寻人时敲锣打铳放鞭炮——&quot;鬼怕这些&quot;；婴儿夜哭的民俗解释是已故长辈回来看、摸得婴儿怕；体质理论是&quot;婴儿元气弱火不旺，故能感觉；常人元气足火旺，鬼不敢近&quot;。</p><h3 id="_5-真实与传说的分层判据-144-110综合" tabindex="-1">5. 真实与传说的分层判据（144/110综合） <a class="header-anchor" href="#_5-真实与传说的分层判据-144-110综合" aria-label="Permalink to &quot;5. 真实与传说的分层判据（144/110综合）&quot;">​</a></h3><p>**判据一：有制度可对照的是真实层。**机构编制、无火化设备跑80公里、运尸车改装、服务链四步、无名尸处置——全部可与社会常识互证。**判据二：有技术可对应的是半真实层。**缝头（现代殡葬确有遗体修复师，且与110的&quot;一针针缝回&quot;完全同构）、冰块防腐（土办法对应现代冷藏）。**判据三：有心理功能的是禁忌层。**磕头赔罪、备喜棺、后厢不坐人、桃树枝——它们未必&quot;灵&quot;，但真实地规训着从业者的行为，是行业心理的真实。**判据四：只有孤证且无机制的是灵异层。**白袍怪人、厕所隔壁死者的声音、冰柜纸人——144作者自己都写&quot;说实话，我也搞不清&quot;，这类内容应原样保留其悬置状态，既不采信也不武断否定。</p><h2 id="四、考古与文物处置-141-演义外壳下的流程骨架" tabindex="-1">四、考古与文物处置（141，演义外壳下的流程骨架） <a class="header-anchor" href="#四、考古与文物处置-141-演义外壳下的流程骨架" aria-label="Permalink to &quot;四、考古与文物处置（141，演义外壳下的流程骨架）&quot;">​</a></h2><h3 id="_1-工地发现古墓的处置链" tabindex="-1">1. 工地发现古墓的处置链 <a class="header-anchor" href="#_1-工地发现古墓的处置链" aria-label="Permalink to &quot;1. 工地发现古墓的处置链&quot;">​</a></h3><p><strong>【实录级流程（帖内陈述合理）】<strong>时代广场打6—7米深地基，挖到5米多时工人发现侧壁露出类似砖块的东西，再一打敲出空洞——<strong>立即报警</strong>；警察勘探发现内部空间很大，随即通知文物管理所；文物管理所专家到场，发现异常后通知权威教授。现场管控：黄色胶带封锁、警察来回巡逻禁止靠近。下墓规程：墓深约5米、不需呼吸设备，但</strong>拴安全绳鱼贯而下</strong>；文物管理所的人已先行下墓装好强光灯。墓内勘验动作：先查随葬品（整个墓无一件随葬品→怀疑被盗）；敲击听音辨材质——棺外敲出沉闷声（陈年老松木）、棺内敲出清脆&quot;叮叮&quot;声（内衬为铁）；发现30公分宽盗洞，勘测确认通向附近下水道。应急延伸：通知警局<strong>提请周边居民锁好门窗、夜间不要轻易外出，加强巡逻，警员全部带枪，武警随时准备支援</strong>。这条&quot;发现→报警→文物部门→专家→封锁→勘验→延伸治安处置&quot;的链路与真实制度基本同构。</p><p>**【实录级】装备日常：**依维柯改装工作车——后座全拆，两侧铁柜，中间工作台，皮夹子里插满钳子、刷子、镊子；上百斤的红色工具包，内装小铁锤、铁铲、铁钎和铁盒。工地的经济逻辑：古墓一出，停工一天损失几十万，工头当场跳脚——<strong>考古发现与工程进度的冲突是真实行业矛盾</strong>。另一处可信细节：考古系冷门，三年只招到两个学生。</p><h3 id="_2-【演绎】必须剥离的部分" tabindex="-1">2. 【演绎】必须剥离的部分 <a class="header-anchor" href="#_2-【演绎】必须剥离的部分" aria-label="Permalink to &quot;2. 【演绎】必须剥离的部分&quot;">​</a></h3><p>僵尸七级分类（尸变/僵尸/跳尸/醒尸/隐尸/魔王/蚩尤级传说）、&quot;天地无依&quot;吊棺风水局、外松内铁的锁尸棺、国安局派驻的11岁全国散打冠军特警保镖、&quot;学生由系主任逐人算命审核、不用上课不用考试&quot;——全是小说设定。判别式：<strong>真实的考古学不研究&quot;无法解释的现象&quot;，恰恰是用可解释的方法研究一切现象。</strong></p><h2 id="五、另两类-知识-的成色-伪档案与集体记忆" tabindex="-1">五、另两类&quot;知识&quot;的成色：伪档案与集体记忆 <a class="header-anchor" href="#五、另两类-知识-的成色-伪档案与集体记忆" aria-label="Permalink to &quot;五、另两类&quot;知识&quot;的成色：伪档案与集体记忆&quot;">​</a></h2><h3 id="_1-伪档案体的构造术-188" tabindex="-1">1. 伪档案体的构造术（188） <a class="header-anchor" href="#_1-伪档案体的构造术-188" aria-label="Permalink to &quot;1. 伪档案体的构造术（188）&quot;">​</a></h3><p>**【演绎】**091气象所（对外搞气象、实为国防部直属超自然调查部队，与美国51区、KGB第17/18监视部队并列）从机构到案件均无实据，但它示范了让虚构显得像解密的三件套：<strong>权限话术</strong>（&quot;绝密的事情是绝对不能打探的，这是任何情况下也不能不遵守的纪律&quot;）、<strong>去英雄化设定</strong>（&quot;即使这样的机构，大部分工作人员也是很普通的正常人&quot;）、<strong>时代质感</strong>（1959饥荒、防化部队&quot;大象鼻子&quot;防毒面具、56式冲锋枪）。前两件是可迁移的写作知识；第三件里饥荒、装备确有真实底子，机构本身纯属虚构。</p><h3 id="_2-市井民俗知识的富矿-163-172" tabindex="-1">2. 市井民俗知识的富矿（163/172） <a class="header-anchor" href="#_2-市井民俗知识的富矿-163-172" aria-label="Permalink to &quot;2. 市井民俗知识的富矿（163/172）&quot;">​</a></h3><p>**【实录级（民俗）】<strong>1976年武汉的物质与语言复原：方言注音茅屎（厕所）、洋火（火柴）、丢跤（摔跤）、拐子（哥哥）、苕货（笨蛋）、扡鱼（杀鱼）；搬罾捕鱼的整套操作；江滩摔跤的江湖规矩（白鹤亮翅以示尊敬、如封似闭应敌）；气功师喷酒点火掌为溺水者施救、救人后当众声明&quot;救不了是天意&quot;的免责话术（民间急救的责任规则）；竹床阵、酸梅汤、备年货。</strong>【演绎】**其&quot;灵异&quot;情节（水底大力、草鬼婆虫蛊）属传说叙事，且帖内多次把闹鬼拆解为高手以内力投石装神弄鬼——作者自己就在消解灵异。</p><h3 id="_3-民间求证方法与记忆的不可靠-168" tabindex="-1">3. 民间求证方法与记忆的不可靠（168） <a class="header-anchor" href="#_3-民间求证方法与记忆的不可靠-168" aria-label="Permalink to &quot;3. 民间求证方法与记忆的不可靠（168）&quot;">​</a></h3><p>**【实录级（方法论）】**楼主为查证&quot;大兴安岭脸盆大的蜘蛛&quot;，去翻80年代初的报纸合订本；引1934年8月14日《盛京时报》营口坠龙、1989年12月《中外书摘》所载1944年牡丹江坠龙（村民组织泼水救护，次日龙迹爬回江中），并指出2004年9月《走近科学》调查营口案的&quot;结论很扯淡&quot;。**这套&quot;回查原始出处&quot;的姿势，比大多数灵异帖的&quot;我朋友说&quot;高级得多。**同时它示范了记忆的边界：全班只有一人看见的小龙，楼主自评&quot;百分之九十是真的，可我到现在也确定不了是不是幻觉&quot;；并提醒&quot;孩子把梦当做现实也是有的&quot;。其&quot;鬼压床进阶版&quot;分级（身体不能动→能睁眼看见周围→能看见自己肉体躺在床上→灵魂离房）与现代医学睡眠瘫痪（sleep paralysis）及出体体验的描述高度吻合——民间观察力可观，解释体系（灵魂）不可采。</p><h2 id="六、判别式-为什么有的行业细节经得起推敲-对照128-141" tabindex="-1">六、判别式：为什么有的行业细节经得起推敲（对照128/141） <a class="header-anchor" href="#六、判别式-为什么有的行业细节经得起推敲-对照128-141" aria-label="Permalink to &quot;六、判别式：为什么有的行业细节经得起推敲（对照128/141）&quot;">​</a></h2><p>**实录帖的知识有三个指纹。**其一，<strong>冗余的真细节</strong>：与主线无关但真实，如运尸车&quot;家属多时后厢加两条长凳&quot;、检察官&quot;跟领导汇报&quot;后才申请鉴定、老太太记得报时——它们不为情节服务，只是作者生活里顺手带出。其二，<strong>系统内的约束</strong>：155的警察要请示搜查证、181的检察官怕证据不足立不了案、144的所长拍领导马屁支使下属夜里回馆——人人都有办不成的事。其三，<strong>承认失败</strong>：悬案就悬着（126）、罪名就降格（181）、&quot;说实话我也搞不清&quot;（144）。</p><p>**演义帖的知识有三个破绽。**其一，<strong>权限失控</strong>：刑警转岗&quot;猎灵局&quot;（128）、大一新生被国宝级教授免课免试收入门下（141）。其二，<strong>服务情节的&quot;细节&quot;</strong>：128的DNA当天出报告、141的盗洞精准通向下水道再通向僵尸——细节存在只为推进剧情，没有一件是多余的。其三，<strong>从不失败</strong>：主角逢凶化吉，体制为其让路。此外还有一篇外指纹：<strong>连载痕迹</strong>（日更三千、完本感言、加QQ群、催更道歉），这是128/141/188与110后段共同的出生证明。</p><p>**结语的三条取舍规则：**一、流程与法条（搜查证、刑事责任能力、罪名收缩、处置链）取实录帖，可当知识用；二、行话与禁忌（跑业务、备喜棺、磕头赔罪）当&quot;行业心理&quot;用，知道即可，不必信其因果；三、一切超自然机制（赶尸行尸、纸人现形、气功钓高人、僵尸分级）一律标&quot;演绎&quot;——它们的真实价值不在&quot;是真的&quot;，而在&quot;一代人曾这样理解和想象死亡与未知&quot;。</p>',65)])])}const p=o(q,[["render",e]]);export{g as __pageData,p as default};
